INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("お！\nあそこに困ってそうな人発見！", 1001, 0, 1, 1, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 2, 0, 1, 0, "春咲 ひより", 1.4, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("大切な人を\n守れるようになりたい…って", 1002, 0, 1, 1, "みんなみたいに\nわたしも強くならなきゃ", 2, 0, 1, 0, "草野 優衣", 1.4, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("キミに必要な集中力と感性が", 1003, 0, 1, 1, "フェンシングを始めてみては？", 2, 0, 1, 0, "士条 怜", 1.4, 0, "少しは磨かれると思いますよ。", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("今日はなにして遊ぶ？", 1004, 0, 1, 1, "ねぇ、にいちゃん！", 2, 0, 1, 0, "穂高 みそぎ", 1.5, 0, "みそぎはねぇ、\nかくれんぼやりたい！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ねぇ…", 1006, 0, 1, 1, "風宮あかりです", 2, 0, 1, 0, "風宮 あかり", 1.4, 0, "私といっしょに…\nいかない？", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("プリンたべたいのー", 1007, 0, 1, 1, "出雲宮子なのー", 2, 0, 1, 0, "出雲 宮子", 1.5, 0, "食べ物の恨みは怖いのー", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("キミもボクの美貌に\n吸い寄せられたんだね。", 1008, 0, 1, 1, "ボクは虹村雪。", 2, 0, 1, 0, "虹村 雪", 1.4, 0, "いいよ。\n見られることは運命さ…", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1009, 0, 1, 1, "フッ…聞いて後悔するがいい！", 2, 0, 1, 0, "柊杏奈", 1.4, 0, "人呼んで「疾風の冥姫」!!", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1010, 0, 1, 1, "マホマホ王国のプリンセス、\nまほ姫どす", 2, 0, 1, 0, "姫宮 真歩", 1.5, 0, "ほんまおおきにやわ～♪", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("生き別れたお兄ちゃんを探して\n三千世界！", 1011, 0, 1, 1, "衣之咲璃乃です！", 2, 0, 1, 0, "衣之咲 璃乃", 1.4, 0, "ここで会ったが\n100年目～！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ち、超能力って…\n何のことかな～？", 1012, 0, 1, 1, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 2, 0, 1, 0, "柏崎 初音", 1.4, 0, "…って、お願い！\n誰にも言わないでおいて～！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("一応カリスマ読モJKやってまっす！", 1016, 0, 1, 1, "ちょす！\n美波鈴奈だよ～♪", 2, 0, 1, 0, "美波 鈴奈", 1.4, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("東京は遊園地みたいなところさー", 1017, 0, 1, 1, "はいたーい。\n喜屋武香織さー。", 2, 0, 1, 0, "喜屋武 香織", 1.4, 0, "でも、沖縄もとってもいいとこさー", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("先生って呼ばれるのは\nくすぐったいから", 1018, 0, 1, 1, "支倉伊緒です。", 2, 0, 1, 0, "支倉 伊緒", 1.4, 0, "イオちゃんって呼んでね。", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あ！/\お兄ちゃ～ん\nまってよ～", 1020, 0, 1, 1, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 2, 0, 1, 0, "茜 ミミ", 1.5, 0, "ミミをおいてかないでぇ～", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あの……\nふぇ……", 1021, 0, 1, 1, "あ…あの…えっと…\n栗…林…くるみ…です……", 2, 0, 1, 0, "栗林 くるみ", 1.5, 0, "ふぇぇぇぇぇん……", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("こんな私に貴重な時間を\n割いていただき、", 1022, 0, 1, 1, "風宮よりです。\nあああああ！", 2, 0, 1, 0, "風宮 より", 1.4, 0, "なんてありがとうございます！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("おにいちゃんどこいくの？\nえ？", 1023, 0, 1, 1, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 2, 0, 1, 0, "北条 綾音", 1.5, 0, "私こっち行きたいー\nね、早く早くー", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ふ、不束者ですが\nどうぞ末永く…って、", 1025, 0, 1, 1, "わっ…わっ…私、\n天野すずめといいます！", 2, 0, 1, 0, "天野 すずめ", 1.4, 0, "これて何か違う…\nあああすみません！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あなたは…運命の……\n伴侶……", 1027, 0, 1, 1, "……クスクス…私は\n…倉石恵理子……", 2, 0, 1, 0, "倉石 恵理子", 1.4, 0, "離しませんわ………\n絶対に…!!", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1028, 0, 1, 1, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 2, 0, 1, 0, "佐々木 咲恋", 1.4, 0, "…そうでしょ？？", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ぇっと…\nキミ、私のこと知らないの?!", 1029, 0, 1, 1, "桜井望だよ！\nよろしくねっ", 2, 0, 1, 0, "桜井 望", 1.4, 0, "あはは、\n私もまだまだだなぁ～", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("初めまして、\n私はニノン・ジュベール申すデス！", 1030, 0, 1, 1, "デケデケデンっ！", 2, 0, 1, 0, "ニノン・ジュベール", 1.4, 0, "ショーグン、\nワタシと一緒に天下統一デース！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("でもって私の隣にいるのが……\nえ、見えない？", 1031, 0, 1, 1, "上喜しのぶです。\n手元のドクロが父です。", 2, 0, 1, 0, "上喜 しのぶ", 1.4, 0, "おかしいですね……", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("けんども\nそれには足りないモンが…", 1033, 0, 1, 1, "目指すはビッグな\nお笑い芸人だっぺ！", 2, 0, 1, 0, "野戸まひる", 1.5, 0, "そう、\nオラのボケに突っ込める相方が…！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ちょっと緊張しちゃって…", 1034, 0, 1, 1, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 2, 0, 1, 0, "綾瀬 ゆかり", 1.4, 0, "ちょ\nちょっと一杯飲んできます…！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("知らない人とは話しちゃいけないので", 1036, 0, 1, 1, "氷川鏡華…です", 2, 0, 1, 0, "氷川 鏡華", 1.5, 0, "これ以上お話しすることは…\nないです！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("……あ、アラーム。", 1038, 0, 1, 1, "柏崎…栞です。", 2, 0, 1, 0, "柏崎 栞", 1.4, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私、一人も友達がいなくて……", 1040, 0, 1, 1, "ふ、双葉碧です。", 2, 0, 1, 0, "双葉 碧", 1.4, 0, "野に咲く花が、\n唯一の話相手です。", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1042, 0, 1, 1, "三角千歌です。", 2, 0, 1, 0, "三角 千歌", 1.4, 0, "そう思っています。", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あぁ？\nお前のそいつの仲間か？", 1043, 0, 1, 1, "安芸真琴だ。", 2, 0, 1, 0, "安芸 真琴", 1.4, 0, "う、疑ってすまなかったな…", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("生けとし生ける全ての者よ！", 1044, 0, 1, 1, "わらわこそは夜を総べる者！", 2, 0, 1, 0, "イリヤ・オーンスタイン", 1.4, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ぐふふふふ……はっ！", 1045, 0, 1, 1, "そこで騎士は妖精を乱暴に……", 2, 0, 1, 0, "遠見 空花", 1.4, 0, "ｌク、クウカに何かご用ですか!?", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("自由気ままで♪\n寝て遊んで、食べてケンカして…", 1046, 0, 1, 1, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 2, 0, 1, 0, "宮坂たまき", 1.4, 0, "う～ん…\n猫ってホントに最高にゃ～♪", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("それでは早速クエストに…", 1048, 0, 1, 1, "大神美冬よ！", 2, 0, 1, 0, "大神 美冬", 1.4, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("クエストもバトルも\n掃除も洗濯も", 1049, 0, 1, 1, "星野静流だよ！", 2, 0, 1, 0, "星野静流", 1.4, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("見ての通りの\nセクシー美少女で", 1050, 0, 1, 1, "アタシは玉泉美咲。", 2, 0, 1, 0, "玉泉美咲", 1.5, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("？？？？", 1052, 0, 1, 1, "？？？", 2, 0, 1, 0, "リマ", 1.4, 0, "？？？？", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("菓子でつろうなどと\n稚拙な策を……", 1053, 0, 1, 1, "モニカ・ヴァイスヴィントだ。", 2, 0, 1, 0, "モニカ・ヴァイスヴィント", 1.5, 0, "そ、そこまでいうなら\nもらってやる", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("菓子でつろうなどと\n稚拙な策を……", 1058, 0, 1, 1, "モニカ・ヴァイスヴィントだ。", 2, 0, 1, 0, "ペコリーヌ", 1.5, 0, "そ、そこまでいうなら\nもらってやる", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("菓子でつろうなどと\n稚拙な策を……", 1059, 0, 1, 1, "モニカ・ヴァイスヴィントだ。", 2, 0, 1, 0, "コッコロ", 1.5, 0, "そ、そこまでいうなら\nもらってやる", 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("菓子でつろうなどと\n稚拙な策を……", 1060, 0, 1, 1, "モニカ・ヴァイスヴィントだ。", 2, 0, 1, 0, "キャル", 1.5, 0, "そ、そこまでいうなら\nもらってやる", 0);
